import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Link, useParams } from 'react-router-dom';
import { 
  Building2, 
  MapPin, 
  FileText, 
  BarChart3,
  ArrowLeft,
  Home,
  Building,
  Factory,
  GraduationCap,
  Plus,
  Eye,
  Settings
} from 'lucide-react';

const PropertyDetails = () => {
  const { id } = useParams();
  const [property, setProperty] = useState(null);
  const [buildings, setBuildings] = useState([]);
  const [activeTab, setActiveTab] = useState('overview');
  const [loading, setLoading] = useState(false);

  // Mock data for demonstration
  const mockProperty = {
    id: 1,
    name: 'Tech Park Campus',
    type: 'campus',
    buildings: 12,
    floors: 48,
    spaces: 286,
    surveys: 156,
    address: '1234 Innovation Drive, Tech City, TC 12345',
    description: 'A state-of-the-art technology campus housing multiple tech companies and startups.',
    totalArea: '125 acres',
    yearBuilt: '2018',
    lastUpdated: '2024-01-15'
  };

  const mockBuildings = [
    {
      id: 1,
      name: 'Innovation Tower A',
      floors: 12,
      spaces: 48,
      surveys: 23,
      status: 'active'
    },
    {
      id: 2,
      name: 'Tech Hub Building B',
      floors: 8,
      spaces: 32,
      surveys: 18,
      status: 'active'
    },
    {
      id: 3,
      name: 'Research Facility C',
      floors: 6,
      spaces: 24,
      surveys: 15,
      status: 'planning'
    },
    {
      id: 4,
      name: 'Data Center D',
      floors: 4,
      spaces: 16,
      surveys: 12,
      status: 'active'
    }
  ];

  useEffect(() => {
    // Use mock data for now
    setProperty(mockProperty);
    setBuildings(mockBuildings);
  }, [id]);

  const getPropertyTypeBadge = (type) => {
    const typeConfig = {
      'residential': {
        label: 'Residential MDU',
        color: 'bg-blue-100 text-blue-800 border-blue-200',
        icon: Home
      },
      'commercial': {
        label: 'Commercial MTU',
        color: 'bg-purple-100 text-purple-800 border-purple-200',
        icon: Building
      },
      'campus': {
        label: 'Campus',
        color: 'bg-green-100 text-green-800 border-green-200',
        icon: GraduationCap
      },
      'industrial': {
        label: 'Industrial Site',
        color: 'bg-orange-100 text-orange-800 border-orange-200',
        icon: Factory
      }
    };

    const config = typeConfig[type] || typeConfig['commercial'];
    const Icon = config.icon;

    return (
      <div className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border ${config.color} text-sm font-medium`}>
        <Icon className="w-3.5 h-3.5" />
        {config.label}
      </div>
    );
  };

  const getStatusBadge = (status) => {
    const statusConfig = {
      'active': {
        color: 'bg-green-100 text-green-800 border-green-200',
        label: 'Active'
      },
      'planning': {
        color: 'bg-yellow-100 text-yellow-800 border-yellow-200',
        label: 'Planning'
      },
      'inactive': {
        color: 'bg-gray-100 text-gray-800 border-gray-200',
        label: 'Inactive'
      }
    };

    const config = statusConfig[status] || statusConfig['active'];

    return (
      <div className={`inline-flex items-center px-3 py-1.5 rounded-full border ${config.color} text-sm font-medium`}>
        {config.label}
      </div>
    );
  };

  const tabs = [
    { id: 'overview', label: 'Overview', icon: Building2 },
    { id: 'buildings', label: 'Buildings', icon: Building },
    { id: 'surveys', label: 'Surveys', icon: FileText },
    { id: 'reports', label: 'Reports', icon: BarChart3 }
  ];

  if (!property) {
    return <div className="w-full p-8 text-center">Loading...</div>;
  }

  return (
    <div className="w-full">
      {/* Header */}
      <div className="bg-white shadow-sm border-b border-gray-200">
        <div className="px-6 lg:px-10 py-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <Link
                to="/properties"
                className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors"
              >
                <ArrowLeft className="w-5 h-5" />
              </Link>
              <div>
                <h1 className="text-2xl font-bold text-gray-900">{property.name}</h1>
                <p className="text-gray-500 mt-1">{property.address}</p>
              </div>
            </div>
            <div className="flex items-center space-x-3">
              {getPropertyTypeBadge(property.type)}
              <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                className="bg-white border border-gray-200 text-gray-700 px-4 py-2 rounded-lg font-medium hover:bg-gray-50 transition-all duration-200 shadow-sm hover:shadow-md flex items-center gap-2"
              >
                <Settings className="w-4 h-4" />
                Edit Property
              </motion.button>
            </div>
          </div>
        </div>
      </div>

      {/* Tabs Navigation */}
      <div className="bg-white border-b border-gray-200">
        <div className="px-6 lg:px-10">
          <div className="flex space-x-8">
            {tabs.map((tab) => {
              const Icon = tab.icon;
              return (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`flex items-center space-x-2 py-4 border-b-2 transition-colors ${
                    activeTab === tab.id
                      ? 'border-blue-500 text-blue-600'
                      : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                  }`}
                >
                  <Icon className="w-4 h-4" />
                  <span className="font-medium">{tab.label}</span>
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* Tab Content */}
      <div className="px-6 lg:px-10 py-8">
        <AnimatePresence mode="wait">
          {activeTab === 'overview' && (
            <motion.div
              key="overview"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="space-y-6"
            >
              {/* Property Overview Stats */}
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <div className="bg-white p-6 rounded-xl border border-gray-200">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-sm text-gray-500">Buildings</p>
                      <p className="text-2xl font-bold text-gray-900">{property.buildings}</p>
                    </div>
                    <div className="p-3 bg-blue-50 rounded-lg">
                      <Building2 className="w-6 h-6 text-blue-600" />
                    </div>
                  </div>
                </div>

                <div className="bg-white p-6 rounded-xl border border-gray-200">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-sm text-gray-500">Floors</p>
                      <p className="text-2xl font-bold text-gray-900">{property.floors}</p>
                    </div>
                    <div className="p-3 bg-green-50 rounded-lg">
                      <Building className="w-6 h-6 text-green-600" />
                    </div>
                  </div>
                </div>

                <div className="bg-white p-6 rounded-xl border border-gray-200">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-sm text-gray-500">Spaces</p>
                      <p className="text-2xl font-bold text-gray-900">{property.spaces}</p>
                    </div>
                    <div className="p-3 bg-purple-50 rounded-lg">
                      <MapPin className="w-6 h-6 text-purple-600" />
                    </div>
                  </div>
                </div>

                <div className="bg-white p-6 rounded-xl border border-gray-200">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-sm text-gray-500">Surveys</p>
                      <p className="text-2xl font-bold text-gray-900">{property.surveys}</p>
                    </div>
                    <div className="p-3 bg-orange-50 rounded-lg">
                      <FileText className="w-6 h-6 text-orange-600" />
                    </div>
                  </div>
                </div>
              </div>

              {/* Property Details */}
              <div className="bg-white rounded-xl border border-gray-200 p-6">
                <h2 className="text-lg font-semibold text-gray-900 mb-4">Property Information</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <p className="text-sm text-gray-500 mb-1">Description</p>
                    <p className="text-gray-900">{property.description}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-500 mb-1">Total Area</p>
                    <p className="text-gray-900">{property.totalArea}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-500 mb-1">Year Built</p>
                    <p className="text-gray-900">{property.yearBuilt}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-500 mb-1">Last Updated</p>
                    <p className="text-gray-900">{property.lastUpdated}</p>
                  </div>
                </div>
              </div>
            </motion.div>
          )}

          {activeTab === 'buildings' && (
            <motion.div
              key="buildings"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="space-y-6"
            >
              <div className="flex items-center justify-between">
                <h2 className="text-lg font-semibold text-gray-900">Buildings ({buildings.length})</h2>
                <motion.button
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  className="bg-white border border-gray-200 text-gray-700 px-4 py-2 rounded-lg font-medium hover:bg-gray-50 transition-all duration-200 shadow-sm hover:shadow-md flex items-center gap-2"
                >
                  <Plus className="w-4 h-4" />
                  Add Building
                </motion.button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {buildings.map((building, index) => (
                  <motion.div
                    key={building.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: index * 0.1 }}
                    className="bg-white rounded-xl border border-gray-200 p-6 hover:shadow-md transition-all duration-200"
                  >
                    <div className="flex items-start justify-between mb-4">
                      <div>
                        <h3 className="text-lg font-semibold text-gray-900">{building.name}</h3>
                        {getStatusBadge(building.status)}
                      </div>
                    </div>

                    <div className="space-y-3 mb-4">
                      <div className="flex items-center justify-between">
                        <span className="text-sm text-gray-500">Floors</span>
                        <span className="text-sm font-medium text-gray-900">{building.floors}</span>
                      </div>
                      <div className="flex items-center justify-between">
                        <span className="text-sm text-gray-500">Spaces</span>
                        <span className="text-sm font-medium text-gray-900">{building.spaces}</span>
                      </div>
                      <div className="flex items-center justify-between">
                        <span className="text-sm text-gray-500">Surveys</span>
                        <span className="text-sm font-medium text-gray-900">{building.surveys}</span>
                      </div>
                    </div>

                    <Link
                      to={`/properties/${property.id}/buildings/${building.id}`}
                      className="w-full text-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium flex items-center justify-center gap-2"
                    >
                      <Eye className="w-4 h-4" />
                      Open Building
                    </Link>
                  </motion.div>
                ))}
              </div>
            </motion.div>
          )}

          {activeTab === 'surveys' && (
            <motion.div
              key="surveys"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="space-y-6"
            >
              <div className="text-center py-12">
                <FileText className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                <h3 className="text-lg font-medium text-gray-900 mb-2">Survey Management</h3>
                <p className="text-gray-500 mb-6">View and manage all surveys for this property</p>
                <Link
                  to="/surveys"
                  className="inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium"
                >
                  Go to Surveys Module
                </Link>
              </div>
            </motion.div>
          )}

          {activeTab === 'reports' && (
            <motion.div
              key="reports"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="space-y-6"
            >
              <div className="text-center py-12">
                <BarChart3 className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                <h3 className="text-lg font-medium text-gray-900 mb-2">Reports & Analytics</h3>
                <p className="text-gray-500 mb-6">Generate detailed reports for this property</p>
                <motion.button
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  className="inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium"
                >
                  Generate Report
                </motion.button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

export default PropertyDetails;
